import { createServer, IncomingMessage, Server, ServerResponse } from 'http';
import { existsSync, readFileSync, statSync } from 'fs';
import { extname, join, resolve, sep } from 'path';
import chokidar, { FSWatcher } from 'chokidar';
import { WebSocket, WebSocketServer } from 'ws';
import { buildSite } from './build';

export interface ServeOptions {
  content: string;
  output: string;
  templates: string;
  port: number;
}

export interface DevServer {
  server: Server;
  wss: WebSocketServer;
  watcher: FSWatcher;
  options: ServeOptions;
  address(): string;
  close(): Promise<void>;
}

export const DEFAULT_PORT = 3000;

const HTML_EXTENSIONS = new Set(['.html', '.htm']);

function isHtmlFile(filePath: string): boolean {
  return HTML_EXTENSIONS.has(extname(filePath).toLowerCase());
}

function mimeTypeFor(filePath: string): string {
  const ext = extname(filePath).toLowerCase();
  const mime: Record<string, string> = {
    '.html': 'text/html; charset=utf-8',
    '.htm': 'text/html; charset=utf-8',
    '.css': 'text/css; charset=utf-8',
    '.js': 'application/javascript; charset=utf-8',
    '.mjs': 'application/javascript; charset=utf-8',
    '.json': 'application/json; charset=utf-8',
    '.map': 'application/json; charset=utf-8',
    '.png': 'image/png',
    '.jpg': 'image/jpeg',
    '.jpeg': 'image/jpeg',
    '.gif': 'image/gif',
    '.svg': 'image/svg+xml',
    '.ico': 'image/x-icon',
    '.webp': 'image/webp',
    '.woff': 'font/woff',
    '.woff2': 'font/woff2',
    '.ttf': 'font/ttf',
  };
  return mime[ext] ?? 'application/octet-stream';
}

export function liveReloadScript(): string {
  return [
    '<script>',
    '(function () {',
    '  var proto = location.protocol === "https:" ? "wss://" : "ws://";',
    '  var ws = new WebSocket(proto + location.host);',
    '  ws.onmessage = function () { location.reload(); };',
    '  ws.onclose = function () { setTimeout(function () { location.reload(); }, 500); };',
    '})();',
    '</script>',
  ].join('\n');
}

export function injectLiveReload(html: string): string {
  const script = liveReloadScript();
  const index = html.lastIndexOf('</body>');
  if (index === -1) return html + script;
  return html.slice(0, index) + script + html.slice(index);
}

function handleRequest(req: IncomingMessage, res: ServerResponse, outputDir: string): void {
  let urlPath: string;
  try {
    urlPath = decodeURIComponent((req.url ?? '/').split('?')[0]);
  } catch {
    res.writeHead(400, { 'Content-Type': 'text/plain' });
    res.end('Bad Request');
    return;
  }
  if (urlPath.endsWith('/')) urlPath += 'index.html';

  const filePath = resolve(outputDir, '.' + urlPath);
  if (!filePath.startsWith(outputDir + sep)) {
    res.writeHead(403, { 'Content-Type': 'text/plain' });
    res.end('Forbidden');
    return;
  }

  let target = filePath;
  if (existsSync(target) && statSync(target).isDirectory()) {
    target = join(target, 'index.html');
  }
  if (!existsSync(target)) {
    res.writeHead(404, { 'Content-Type': 'text/plain' });
    res.end('Not Found');
    return;
  }

  const contents = readFileSync(target);
  const headers: Record<string, string> = { 'Content-Type': mimeTypeFor(target) };
  res.writeHead(200, headers);
  if (isHtmlFile(target)) {
    res.end(injectLiveReload(contents.toString('utf8')));
    return;
  }
  res.end(contents);
}

export function startDevServer(options: ServeOptions): DevServer {
  const contentDir = resolve(options.content);
  const templatesDir = resolve(options.templates);
  const outputDir = resolve(options.output);

  buildSite(contentDir, outputDir, templatesDir);

  const wss = new WebSocketServer({ noServer: true });

  function notifyClients(): void {
    for (const client of wss.clients) {
      if (client.readyState === WebSocket.OPEN) {
        try {
          client.send('reload');
        } catch {
          // client may have closed between the readyState check and send
        }
      }
    }
  }

  function rebuild(): void {
    try {
      buildSite(contentDir, outputDir, templatesDir);
      notifyClients();
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      process.stderr.write(`Rebuild error: ${message}\n`);
    }
  }

  const watcher = chokidar.watch([contentDir, templatesDir], { ignoreInitial: true });
  watcher.on('change', rebuild);
  watcher.on('add', rebuild);
  watcher.on('unlink', rebuild);
  watcher.on('addDir', rebuild);
  watcher.on('unlinkDir', rebuild);

  const server = createServer((req, res) => {
    handleRequest(req, res, outputDir);
  });

  server.on('upgrade', (req, socket, head) => {
    wss.handleUpgrade(req, socket, head, (ws) => {
      wss.emit('connection', ws, req);
    });
  });

  server.listen(options.port);

  return {
    server,
    wss,
    watcher,
    options,
    address(): string {
      const addr = server.address();
      if (addr === null || typeof addr === 'string') return `http://localhost:${options.port}`;
      return `http://localhost:${addr.port}`;
    },
    close(): Promise<void> {
      return new Promise((resolveClose, rejectClose) => {
        wss.close();
        watcher
          .close()
          .then(() => {
            server.close((err) => {
              if (err) rejectClose(err);
              else resolveClose();
            });
          })
          .catch(rejectClose);
      });
    },
  };
}

#!/usr/bin/env node
import { buildSite } from './build';
import { Page } from './page';
import { DEFAULT_PORT, ServeOptions, startDevServer } from './serve';

export interface BuildOptions {
  content: string;
  output: string;
  templates: string;
}

export type CliOptions = BuildOptions | ServeOptions;

export interface ParsedCli {
  command: 'build' | 'serve';
  options: CliOptions;
}

const DEFAULT_CONTENT = './content';
const DEFAULT_OUTPUT = './dist';
const DEFAULT_TEMPLATES = './templates';

function usage(): string {
  return [
    'Usage: ssg <command> [options]',
    '',
    'Commands:',
    '  build   Build the static site',
    '  serve   Start the development server with live reload',
    '',
    'Options:',
    '  --content <dir>    Markdown source directory (default: ./content)',
    '  --output <dir>     Output directory (default: ./dist)',
    '  --templates <dir>  Template directory (default: ./templates)',
    '  --port <number>    Port for the dev server (default: 3000)',
    '  -h, --help         Show this help',
  ].join('\n');
}

function parseFlagValue(argv: string[], flag: string, index: number): string | null {
  const arg = argv[index];
  if (arg === flag) {
    const value = argv[index + 1];
    return value !== undefined ? value : null;
  }
  if (arg.startsWith(`${flag}=`)) {
    return arg.slice(flag.length + 1);
  }
  return null;
}

export function parseArgs(argv: string[]): ParsedCli | null {
  const args = argv.slice();
  const command = args.shift();
  if (command === undefined || command === '-h' || command === '--help') return null;
  if (command !== 'build' && command !== 'serve') return null;

  const options: BuildOptions = { content: DEFAULT_CONTENT, output: DEFAULT_OUTPUT, templates: DEFAULT_TEMPLATES };
  let port = DEFAULT_PORT;

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '-h' || arg === '--help') return null;
    const contentValue = parseFlagValue(args, '--content', i);
    if (contentValue !== null) {
      options.content = contentValue;
      if (args[i] === '--content') i++;
      continue;
    }
    const outputValue = parseFlagValue(args, '--output', i);
    if (outputValue !== null) {
      options.output = outputValue;
      if (args[i] === '--output') i++;
      continue;
    }
    const templatesValue = parseFlagValue(args, '--templates', i);
    if (templatesValue !== null) {
      options.templates = templatesValue;
      if (args[i] === '--templates') i++;
      continue;
    }
    if (command === 'serve') {
      const portValue = parseFlagValue(args, '--port', i);
      if (portValue !== null) {
        const parsedPort = Number(portValue);
        if (Number.isInteger(parsedPort) && parsedPort > 0 && parsedPort <= 65535) {
          port = parsedPort;
        } else {
          return null;
        }
        if (args[i] === '--port') i++;
        continue;
      }
    }
    return null;
  }

  if (command === 'serve') {
    return { command, options: { ...options, port } };
  }
  return { command, options };
}

export function run(argv: string[]): number {
  const parsed = parseArgs(argv);
  if (parsed === null) {
    process.stdout.write(usage() + '\n');
    return 1;
  }

  try {
    if (parsed.command === 'serve') {
      const options = parsed.options as ServeOptions;
      const devServer = startDevServer(options);
      process.stdout.write(`Serving ${options.output} at ${devServer.address()}\n`);
      process.stdout.write(`Watching ${options.content} and ${options.templates} for changes...\n`);
      return 0;
    }
    const pages: Page[] = buildSite(parsed.options.content, parsed.options.output, parsed.options.templates);
    process.stdout.write(`Built ${pages.length} page(s) into ${parsed.options.output}\n`);
    return 0;
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    process.stderr.write(`Error: ${message}\n`);
    return 1;
  }
}

function main(): void {
  process.exitCode = run(process.argv.slice(2));
}

if (require.main === module) {
  main();
}

